'use client';

import { useEffect, useId, useMemo, useRef, useState, type CSSProperties, type ReactNode, type PointerEvent as ReactPointerEvent } from 'react';
import './logo-orbit.css';

export interface LogoOrbitItem {
  id: string;
  label: string;
  /** Decorative logo artwork without nested controls. */
  logo: ReactNode;
  orbit?: 'inner' | 'outer';
  /** Badge diameter at a 560px stage, scaled with its container. */
  size?: number;
  href?: string;
}

export interface LogoOrbitProps {
  items: LogoOrbitItem[];
  center?: ReactNode;
  centerLabel?: string;
  /** Seconds per outer revolution. Inner logos travel at 70% of this duration. */
  duration?: number;
  reverse?: boolean;
  paused?: boolean;
  defaultSelectedId?: string;
  onItemSelect?: (id: string) => void;
  className?: string;
}

/** A fixed hub surrounded by orbiting, upright integration badges. */
export function LogoOrbit({ items, center, centerLabel = 'Workspace', duration = 60, reverse = false, paused = false, defaultSelectedId, onItemSelect, className = '' }: LogoOrbitProps) {
  const root = useRef<HTMLElement>(null);
  const captionId = useId();
  const [selection, setSelection] = useState(defaultSelectedId);
  const [manualPaused, setManualPaused] = useState(false);
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const [activity, setActivity] = useState({ ready: false, visible: false, foreground: true, reduced: false });
  const safeItems = useMemo(() => {
    const seen = new Set<string>();
    let innerCount = 0;
    return items.filter(item => {
      if (!item.id.trim() || !item.label.trim() || seen.has(item.id)) return false;
      seen.add(item.id);
      return true;
    }).slice(0, 12).map(item => {
      const orbit = item.orbit === 'inner' && innerCount < 6 ? 'inner' : 'outer';
      if (orbit === 'inner') innerCount++;
      const size = Number.isFinite(item.size) ? Math.max(44, Math.min(orbit === 'inner' ? 64 : 80, item.size!)) : orbit === 'inner' ? 56 : 68;
      return { ...item, orbit, size };
    });
  }, [items]);
  const selected = safeItems.find(item => item.id === selection) ?? safeItems[0];
  const held = safeItems.some(item => item.id === hoveredId || item.id === focusedId);
  const seconds = Number.isFinite(duration) ? Math.max(20, Math.min(180, duration)) : 60;
  const running = activity.ready && activity.visible && activity.foreground && !activity.reduced && !paused && !manualPaused && !held && safeItems.length > 0;

  useEffect(() => {
    setHoveredId(value => safeItems.some(item => item.id === value) ? value : null);
    setFocusedId(value => safeItems.some(item => item.id === value) ? value : null);
  }, [safeItems]);

  useEffect(() => {
    const element = root.current;
    if (!element) return;
    const media = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => setActivity(value => ({ ...value, ready: true, reduced: media.matches, foreground: !document.hidden }));
    const observer = typeof IntersectionObserver === 'undefined' ? null : new IntersectionObserver(([entry]) => {
      if (entry) setActivity(value => ({ ...value, visible: entry.isIntersecting }));
    });
    observer?.observe(element);
    if (!observer) setActivity(value => ({ ...value, visible: true }));
    sync();
    media.addEventListener('change', sync);
    document.addEventListener('visibilitychange', sync);
    return () => { observer?.disconnect(); media.removeEventListener('change', sync); document.removeEventListener('visibilitychange', sync); };
  }, []);

  return <section ref={root} className={`ac-logo-orbit ${className}`.trim()} aria-label={`${centerLabel} logo orbit`} aria-describedby={captionId} data-running={running} data-reverse={reverse}>
    <div className="ac-logo-orbit-stage" onPointerLeave={() => setHoveredId(null)}>
      <div className="ac-logo-orbit-rings" aria-hidden="true"><i/><i/><i/></div>
      {(['outer', 'inner'] as const).map(orbit => {
        const group = safeItems.filter(item => item.orbit === orbit);
        if (!group.length) return null;
        return <div key={orbit} className="ac-logo-orbit-track" data-orbit={orbit} style={{ '--ac-logo-orbit-duration': `${seconds * (orbit === 'inner' ? .7 : 1)}s` } as CSSProperties}>
          {group.map((item, index) => {
            const angle = (index / group.length * 360 + (orbit === 'outer' ? -100 : -140)) * Math.PI / 180;
            const radius = orbit === 'outer' ? 210 : 132;
            const style = { left: `${50 + Math.cos(angle) * radius / 5.6}%`, top: `${50 + Math.sin(angle) * radius / 5.6}%`, width: `${item.size / 5.6}%` };
            const common = {
              className: 'ac-logo-orbit-badge',
              'aria-label': item.label,
              'data-selected': selected?.id === item.id,
              onPointerEnter: (event: ReactPointerEvent<HTMLElement>) => { if (event.pointerType !== 'touch') setHoveredId(item.id); },
              onPointerLeave: () => setHoveredId(value => value === item.id ? null : value),
              onFocus: () => setFocusedId(item.id),
              onBlur: () => setFocusedId(value => value === item.id ? null : value),
              onClick: () => { setSelection(item.id); onItemSelect?.(item.id); },
            };
            const content = <span className="ac-logo-orbit-logo" aria-hidden="true">{item.logo ?? item.label.slice(0, 1)}</span>;
            return <div key={item.id} className="ac-logo-orbit-position" style={style}>
              {item.href ? <a {...common} href={item.href}>{content}</a> : <button {...common} type="button" aria-pressed={selected?.id === item.id}>{content}</button>}
            </div>;
          })}
        </div>;
      })}
      <div className="ac-logo-orbit-center" role="img" aria-label={centerLabel}>{center ?? <svg viewBox="0 0 48 48" fill="none" aria-hidden="true"><path d="m10 36 14-25 14 25H10Z" stroke="currentColor" strokeWidth="3" strokeLinejoin="round"/><path d="M17 29h14" stroke="currentColor" strokeWidth="3"/></svg>}</div>
    </div>
    <footer className="ac-logo-orbit-footer">
      <p id={captionId} aria-live="polite" aria-atomic="true">{selected ? <><span className="ac-logo-orbit-dot" aria-hidden="true"/><strong>{selected.label}</strong><span>→ {centerLabel}</span></> : 'No logos configured.'}</p>
      <button type="button" className="ac-logo-orbit-motion" disabled={activity.reduced || paused || safeItems.length === 0} onClick={() => setManualPaused(value => !value)}><span aria-hidden="true">{manualPaused || paused || activity.reduced ? '▷' : 'Ⅱ'}</span>{activity.reduced ? 'Motion reduced' : paused ? 'Motion paused' : manualPaused ? 'Play motion' : 'Pause motion'}</button>
    </footer>
  </section>;
}

.ac-logo-orbit, .ac-logo-orbit * { box-sizing: border-box; }
.ac-logo-orbit { --ac-logo-orbit-surface: #f5f6f7; --ac-logo-orbit-ink: #19334c; --ac-logo-orbit-hub: #062750; --ac-logo-orbit-ring: #e9f0f8; --ac-logo-orbit-ring-inner: #e1ebf5; position: relative; width: 100%; max-width: 560px; margin-inline: auto; color: var(--ac-logo-orbit-ink); background: var(--ac-logo-orbit-surface); font-family: Arial, Helvetica, sans-serif; container-type: inline-size; }
.ac-logo-orbit-stage { position: relative; width: 100%; aspect-ratio: 1; isolation: isolate; }
.ac-logo-orbit-rings { position: absolute; inset: 0; pointer-events: none; }
.ac-logo-orbit-rings i { position: absolute; inset: 50% auto auto 50%; display: block; border-radius: 50%; transform: translate(-50%, -50%); aspect-ratio: 1; width: 75%; background: var(--ac-logo-orbit-ring); }
.ac-logo-orbit-rings i:nth-child(2) { width: 51%; background: var(--ac-logo-orbit-ring-inner); }
.ac-logo-orbit-rings i:nth-child(3) { width: 29%; background: #d4e2ef; opacity: .7; }
.ac-logo-orbit-track { position: absolute; inset: 0; pointer-events: none; transform-origin: center; animation: ac-logo-orbit-revolve var(--ac-logo-orbit-duration, 60s) linear infinite; animation-play-state: paused; }
.ac-logo-orbit-position { position: absolute; aspect-ratio: 1; transform: translate(-50%, -50%); min-width: 36px; }
.ac-logo-orbit-badge { position: relative; display: grid; place-items: center; width: 100%; height: 100%; padding: 0; border: 1px solid #fff; border-radius: 50%; background: #fff; color: #244669; box-shadow: 0 7px 17px #15365312, 0 1px 3px #15365306; cursor: pointer; pointer-events: auto; text-decoration: none; -webkit-tap-highlight-color: transparent; animation: ac-logo-orbit-upright var(--ac-logo-orbit-duration, 60s) linear infinite; animation-play-state: paused; }
.ac-logo-orbit[data-running="true"] :is(.ac-logo-orbit-track, .ac-logo-orbit-badge) { animation-play-state: running; }
.ac-logo-orbit[data-reverse="true"] :is(.ac-logo-orbit-track, .ac-logo-orbit-badge) { animation-direction: reverse; }
.ac-logo-orbit-badge:hover { box-shadow: 0 8px 22px #15365320, 0 0 0 3px #d4e2ef; }
.ac-logo-orbit-badge:focus-visible { outline: 3px solid #3e78bc; outline-offset: 5px; }
.ac-logo-orbit-logo { display: grid; place-items: center; width: 56%; height: 56%; pointer-events: none; font-size: clamp(15px, 4cqi, 26px); font-weight: 600; }
.ac-logo-orbit-logo > :is(svg, img) { display: block; width: 100%; height: 100%; object-fit: contain; }
.ac-logo-orbit-center { position: absolute; z-index: 2; top: 50%; left: 50%; display: grid; place-items: center; width: 23%; aspect-ratio: 1; padding: 5.4%; border: 1px solid #ffffff40; border-radius: 50%; transform: translate(-50%, -50%); background: var(--ac-logo-orbit-hub); color: #fff; box-shadow: 0 0 0 11px #d4e1ed70, 0 9px 23px #08284c25; pointer-events: none; font-size: clamp(24px, 8cqi, 48px); font-weight: 600; }
.ac-logo-orbit-center > :is(svg, img) { display: block; width: 100%; height: 100%; object-fit: contain; }
.ac-logo-orbit-footer { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 0 12px; min-height: 56px; padding: 5px 16px; color: #657688; font: 10px/1.5 ui-monospace, SFMono-Regular, Consolas, monospace; }
.ac-logo-orbit-footer p { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin: 6px 0; }
.ac-logo-orbit-footer strong { color: #244669; font-weight: 500; }
.ac-logo-orbit-dot { width: 4px; height: 4px; border-radius: 50%; background: #7194b8; }
.ac-logo-orbit-motion { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 44px; padding: 0; border: 0; background: transparent; color: inherit; font: inherit; cursor: pointer; }
.ac-logo-orbit-motion:hover:not(:disabled) { color: #244669; text-decoration: underline; text-underline-offset: 4px; }
.ac-logo-orbit-motion:focus-visible { outline: 2px solid #3e78bc; outline-offset: 3px; }
.ac-logo-orbit-motion:disabled { opacity: .6; cursor: default; }
@keyframes ac-logo-orbit-revolve { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
@keyframes ac-logo-orbit-upright { from { transform: rotate(0deg); } to { transform: rotate(-360deg); } }
@media (prefers-reduced-motion: reduce) { .ac-logo-orbit :is(.ac-logo-orbit-track, .ac-logo-orbit-badge) { animation-play-state: paused !important; } }

'use client'

import { useEffect, useId, useMemo, useRef, useState, type CSSProperties, type ReactNode } from 'react'
import './orbit-network.css'

export interface OrbitNetworkNode {
  id: string
  label: string
  /** Decorative artwork. The button receives its accessible name from label. */
  symbol?: ReactNode
}

export interface OrbitNetworkProps {
  nodes?: OrbitNetworkNode[]
  center?: ReactNode
  centerLabel?: string
  defaultSelectedId?: string
  onNodeChange?: (id: string) => void
  /** External pause. The visitor can also pause from the component's own control. */
  paused?: boolean
  /** Animation multiplier, clamped between 0.2 and 2. */
  speed?: number
  color?: string
  className?: string
}

const paths = [
  'M5 7c0-4 14-4 14 0s-14 4-14 0m0 0v10c0 4 14 4 14 0V7M5 12c0 4 14 4 14 0',
  'm12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5',
  'm4 5 6 7-6 7m7-14 6 7-6 7m9-14v14',
  'M4 19V9m5 10V4m6 15v-7m5 7V7',
  'm12 3 2.3 6.7L21 12l-6.7 2.3L12 21l-2.3-6.7L3 12l6.7-2.3L12 3Z',
  'M4 7h16M4 12h16M4 17h16M8 4v6m8-1v6m-7-1v6',
  'M12 3v6m0 6v6M3 12h6m6 0h6M6 6l4 4m4 4 4 4M6 18l4-4m4-4 4-4',
  'm12 3 8 4v10l-8 4-8-4V7l8-4Zm0 0v18M4 7l8 5 8-5',
]

function SymbolMark({ index }: { index: number }) {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="square" strokeLinejoin="miter" aria-hidden="true"><path d={paths[index % paths.length]} /></svg>
}

const defaultNodes: OrbitNetworkNode[] = ['Database', 'Storage', 'Queue', 'Analytics', 'Search', 'Automation', 'Events', 'Compute'].map((label, index) => ({
  id: label.toLowerCase(), label, symbol: <SymbolMark index={index} />,
}))

function point(index: number, count: number, radius: number) {
  const angle = (index / Math.max(1, count)) * Math.PI * 2 - Math.PI / 2
  return { x: 250 + Math.cos(angle) * radius, y: 250 + Math.sin(angle) * radius }
}

/** A rotating integration map with an ASCII particle field and inbound packets. */
export function OrbitNetwork({ nodes = defaultNodes, center, centerLabel = 'Workspace', defaultSelectedId, onNodeChange, paused = false, speed = 1, color = '#5d43ee', className = '' }: OrbitNetworkProps) {
  const captionId = useId()
  const stage = useRef<HTMLDivElement>(null)
  const canvas = useRef<HTMLCanvasElement>(null)
  const packets = useRef<(SVGRectElement | null)[]>([])
  const phase = useRef(0)
  const [selection, setSelection] = useState(defaultSelectedId)
  const [manualPaused, setManualPaused] = useState(false)
  const [interacting, setInteracting] = useState(false)
  const [reducedMotion, setReducedMotion] = useState(false)
  const safeNodes = useMemo(() => {
    const seen = new Set<string>()
    return nodes.filter(node => {
      if (!node.id || !node.label || seen.has(node.id)) return false
      seen.add(node.id)
      return true
    }).slice(0, 12)
  }, [nodes])
  const selected = safeNodes.find(node => node.id === selection) ?? safeNodes[0]
  const safeSpeed = Number.isFinite(speed) ? Math.max(0.2, Math.min(2, speed)) : 1
  const count = safeNodes.length

  useEffect(() => {
    const element = stage.current
    const surface = canvas.current
    if (!element || !surface) return
    const context = surface.getContext('2d')
    const motion = window.matchMedia('(prefers-reduced-motion: reduce)')
    let frame: number | null = null
    let lastTime = 0
    let lastDraw = -Infinity
    let visible = typeof IntersectionObserver === 'undefined'
    let alive = true
    let scale = 1
    let particleColor = color
    const canRun = () => alive && count > 0 && !paused && !manualPaused && !interacting && !motion.matches && visible && !document.hidden

    function draw(time: number) {
      const angle = time * 2.5
      element!.style.setProperty('--ac-orbit-turn', `${angle.toFixed(4)}deg`)
      for (let index = 0; index < count * 2; index++) {
        const spoke = Math.floor(index / 2)
        const offset = index % 2
        const progress = (time / (3.2 + spoke % 3 * 0.4) + spoke * 0.17 + offset * 0.5) % 1
        const position = point(spoke, count, 174 * (1 - progress))
        const packet = packets.current[index]
        packet?.setAttribute('x', (position.x - 2).toFixed(3))
        packet?.setAttribute('y', (position.y - 2).toFixed(3))
        packet?.setAttribute('opacity', progress < 0.04 || progress > 0.86 ? '0' : offset ? '0.45' : '1')
      }
      if (!context) return
      context.setTransform(scale, 0, 0, scale, 0, 0)
      context.clearRect(0, 0, 500, 500)
      context.fillStyle = particleColor
      context.font = '6px ui-monospace, SFMono-Regular, Consolas, monospace'
      context.textAlign = 'center'
      context.textBaseline = 'middle'
      const flicker = Math.floor(time * 4)
      for (let row = 0; row < 65; row++) {
        for (let col = 0; col < 65; col++) {
          const x = 10 + col * 7.5
          const y = 10 + row * 7.5
          const dx = x - 250
          const dy = y - 250
          const distance = Math.hypot(dx, dy)
          const seed = (col * 31 + row * 47 + col * row * 7) % 101
          const annulus = Math.max(0, 1 - Math.abs(distance - 158) / 74)
          const wave = 0.64 + 0.36 * Math.sin(Math.atan2(dy, dx) * 5 + distance / 28 - time * 0.85)
          const density = annulus * wave
          if (distance < 82 || distance > 240) continue
          context.globalAlpha = distance > 223 ? 0.09 : Math.min(0.78, 0.1 + density * 0.64)
          if (density > 0.28 && seed % 4 !== 0) {
            const glyph = ['+', '×', ':', '·', '+', '×'][(seed + flicker + Math.floor(distance / 18)) % 6]
            context.fillText(glyph, x, y)
          } else context.fillRect(x, y, seed % 5 === 0 ? 1 : 0.7, seed % 5 === 0 ? 1 : 0.7)
        }
      }
      context.globalAlpha = 1
    }

    function tick(timestamp: number) {
      frame = null
      if (!canRun()) return
      if (lastTime) phase.current += Math.min(64, timestamp - lastTime) / 1000 * safeSpeed
      lastTime = timestamp
      if (timestamp - lastDraw >= 32) {
        draw(phase.current)
        lastDraw = timestamp
      }
      frame = requestAnimationFrame(tick)
    }

    function sync() {
      if (frame !== null) cancelAnimationFrame(frame)
      frame = null
      lastTime = 0
      draw(phase.current)
      if (canRun()) frame = requestAnimationFrame(tick)
    }

    function resize() {
      const width = element!.getBoundingClientRect().width || 500
      const pixels = Math.max(1, Math.round(width * Math.min(window.devicePixelRatio || 1, 2)))
      surface!.width = pixels
      surface!.height = pixels
      scale = pixels / 500
      particleColor = window.getComputedStyle(surface!).color
      draw(phase.current)
    }

    function preferenceChanged() { setReducedMotion(motion.matches); sync() }
    const intersection = typeof IntersectionObserver === 'undefined' ? null : new IntersectionObserver(entries => {
      visible = entries.some(entry => entry.isIntersecting)
      sync()
    }, { threshold: 0.05 })
    const resizeObserver = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(resize)
    intersection?.observe(element)
    resizeObserver?.observe(element)
    motion.addEventListener('change', preferenceChanged)
    document.addEventListener('visibilitychange', sync)
    window.addEventListener('resize', resize)
    setReducedMotion(motion.matches)
    resize()
    sync()
    return () => {
      alive = false
      if (frame !== null) cancelAnimationFrame(frame)
      intersection?.disconnect()
      resizeObserver?.disconnect()
      motion.removeEventListener('change', preferenceChanged)
      document.removeEventListener('visibilitychange', sync)
      window.removeEventListener('resize', resize)
    }
  }, [color, count, safeSpeed, paused, manualPaused, interacting])

  return <section className={`ac-orbit-network ${className}`.trim()} aria-label={`${centerLabel} integration network`} style={{ '--ac-orbit-color': color } as CSSProperties}>
    <div className="ac-orbit-network-stage" ref={stage}>
      <canvas ref={canvas} className="ac-orbit-network-field" aria-hidden="true" />
      <svg className="ac-orbit-network-geometry" viewBox="0 0 500 500" fill="none" aria-hidden="true">
        <g className="ac-orbit-network-rotor">
          <circle cx="250" cy="250" r="183" className="ac-orbit-network-ring" />
          {count > 1 && <><polygon points={safeNodes.map((_, index) => { const p = point(index, count, 174); return `${p.x.toFixed(3)},${p.y.toFixed(3)}` }).join(' ')} className="ac-orbit-network-polygon" /><polygon points={safeNodes.map((_, index) => { const p = point(index, count, 96); return `${p.x.toFixed(3)},${p.y.toFixed(3)}` }).join(' ')} className="ac-orbit-network-polygon" /></>}
          {safeNodes.map((node, index) => {
            const outer = point(index, count, 174)
            const inner = point(index, count, 96)
            return <g key={node.id}>
              <line x1="250" y1="250" x2={outer.x} y2={outer.y} className={`ac-orbit-network-spoke${selected?.id === node.id ? ' is-selected' : ''}`} />
              <rect x={inner.x - 3} y={inner.y - 3} width="6" height="6" className="ac-orbit-network-junction" />
              {[0, 1].map(offset => { const initial = point(index, count, offset ? 115 : 59); return <rect key={offset} ref={value => { packets.current[index * 2 + offset] = value }} x={initial.x - 2} y={initial.y - 2} width="4" height="4" className="ac-orbit-network-packet" /> })}
            </g>
          })}
        </g>
      </svg>
      <div className="ac-orbit-network-nodes ac-orbit-network-rotor">
        {safeNodes.map((node, index) => {
          const p = point(index, count, 174)
          return <button key={node.id} type="button" className="ac-orbit-network-node" style={{ left: `${p.x / 5}%`, top: `${p.y / 5}%` }} aria-label={node.label} aria-pressed={selected?.id === node.id} aria-describedby={captionId}
            onPointerEnter={() => setInteracting(true)} onPointerLeave={() => { if (!stage.current?.contains(document.activeElement)) setInteracting(false) }} onFocus={() => setInteracting(true)} onBlur={() => setInteracting(false)}
            onClick={() => { setSelection(node.id); onNodeChange?.(node.id) }}>
            <span className="ac-orbit-network-tile" aria-hidden="true">{node.symbol ?? node.label.slice(0, 1)}</span>
          </button>
        })}
      </div>
      <div className="ac-orbit-network-center" role="img" aria-label={centerLabel}>{center ?? <SymbolMark index={6} />}</div>
    </div>
    <footer className="ac-orbit-network-footer">
      <p id={captionId} aria-live="polite" aria-atomic="true">{selected ? <><span className="ac-orbit-network-status" aria-hidden="true" /><strong>{selected.label}</strong><span>→ {centerLabel}</span></> : 'No connections configured.'}</p>
      <button type="button" className="ac-orbit-network-pause" disabled={reducedMotion || paused} onClick={() => setManualPaused(value => !value)}>
        <span aria-hidden="true">{reducedMotion || paused || manualPaused ? '▶' : 'Ⅱ'}</span>{reducedMotion ? 'Motion reduced' : paused ? 'Motion paused' : manualPaused ? 'Resume motion' : 'Pause motion'}
      </button>
    </footer>
  </section>
}

.ac-orbit-network, .ac-orbit-network * { box-sizing: border-box; }
.ac-orbit-network {
  --ac-orbit-paper: #faf9f6;
  --ac-orbit-ink: #303127;
  --ac-orbit-muted: #72736d;
  --ac-orbit-line: #b6b4bf;
  position: relative;
  width: 100%;
  max-width: 640px;
  margin-inline: auto;
  color: var(--ac-orbit-ink);
  background: var(--ac-orbit-paper);
  container-type: inline-size;
  font-family: Arial, Helvetica, sans-serif;
}
.ac-orbit-network-stage { position: relative; width: 100%; aspect-ratio: 1; isolation: isolate; overflow: hidden; background-image: radial-gradient(var(--ac-orbit-color, #5d43ee) .4px, transparent .5px); background-size: 7.5px 7.5px; }
.ac-orbit-network-field { position: absolute; inset: 0; width: 100%; height: 100%; color: var(--ac-orbit-color, #5d43ee); background: var(--ac-orbit-paper); }
.ac-orbit-network-geometry { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.ac-orbit-network-rotor { transform: rotate(var(--ac-orbit-turn, 0deg)); transform-origin: 50% 50%; }
.ac-orbit-network-ring { stroke: var(--ac-orbit-line); stroke-width: .65; opacity: .55; }
.ac-orbit-network-polygon { stroke: var(--ac-orbit-line); stroke-width: .8; }
.ac-orbit-network-spoke { stroke: var(--ac-orbit-line); stroke-width: .8; }
.ac-orbit-network-spoke.is-selected { stroke: var(--ac-orbit-color, #5d43ee); stroke-width: 1; }
.ac-orbit-network-junction { fill: var(--ac-orbit-paper); stroke: #85848b; stroke-width: .8; }
.ac-orbit-network-packet { fill: var(--ac-orbit-color, #5d43ee); }
.ac-orbit-network-nodes { position: absolute; inset: 0; pointer-events: none; }
.ac-orbit-network-node {
  position: absolute;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
