  box-sizing: border-box;
  width: fit-content;
  max-width: 100%;
  padding: 7px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  border-radius: var(--ac-sliding-radius, 999px);
  color: var(--ac-sliding-color, #56574e);
