}

.ac-spine-sleeve {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
  width: max(44px, var(--ac-spine-width, 56px));
  min-height: 208px;
  border-radius: 4px 7px 7px 4px;
