  box-shadow: 3px 3px 0 color-mix(in srgb, var(--ac-spine-cover-color) 45%, #111), 7px 10px 10px #16170e26, inset 1px 0 0 #fff5;
  transform: rotateY(-12deg) translateY(3px);
