import type { CSSProperties, HTMLAttributes, PointerEvent } from 'react'
import './spotlight-card.css'

export interface SpotlightCardProps extends HTMLAttributes<HTMLDivElement> {
  /** The accent color of the light that follows the pointer. */
  color?: string
}

export function SpotlightCard({
  children,
  className = '',
  color = '#d7ee9e',
  style,
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  ...props
}: SpotlightCardProps) {
  function moveLight(event: PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event)
    if (
      event.defaultPrevented ||
      event.pointerType !== 'mouse' ||
      window.matchMedia('(prefers-reduced-motion: reduce)').matches
    ) return

    const bounds = event.currentTarget.getBoundingClientRect()
    event.currentTarget.style.setProperty('--ac-spotlight-x', `${event.clientX - bounds.left}px`)
    event.currentTarget.style.setProperty('--ac-spotlight-y', `${event.clientY - bounds.top}px`)
  }

  function resetLight(event: PointerEvent<HTMLDivElement>) {
    onPointerLeave?.(event)
    event.currentTarget.style.removeProperty('--ac-spotlight-x')
    event.currentTarget.style.removeProperty('--ac-spotlight-y')
  }

  return (
    <div
      {...props}
      className={`ac-spotlight-card ${className}`.trim()}
      style={{ '--ac-spotlight-color': color, ...style } as CSSProperties}
      onPointerMove={moveLight}
      onPointerLeave={resetLight}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        event.currentTarget.style.removeProperty('--ac-spotlight-x')
        event.currentTarget.style.removeProperty('--ac-spotlight-y')
      }}
    >
      {children}
    </div>
  )
}

.ac-spotlight-card {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border: 1px solid var(--ac-card-border, rgb(255 255 255 / 12%));
  border-radius: var(--ac-card-radius, 16px);
  background: var(--ac-card-surface, #191b18);
  color: var(--ac-card-color, #e9e9df);
}

.ac-spotlight-card::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(
    480px circle at var(--ac-spotlight-x, 50%) var(--ac-spotlight-y, 50%),
    color-mix(in srgb, var(--ac-spotlight-color) 20%, transparent),
    transparent 72%
  );
  opacity: 0;
  transition: opacity 300ms ease;
  pointer-events: none;
  content: '';
}

.ac-spotlight-card:hover::before,
.ac-spotlight-card:focus-within::before {
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .ac-spotlight-card {
    --ac-spotlight-x: 50% !important;
    --ac-spotlight-y: 50% !important;
  }

  .ac-spotlight-card::before {
    transition: none;
  }
}

@media (hover: none) {
  .ac-spotlight-card::before {
    opacity: 0.65;
  }
}

'use client'

import type { CSSProperties, HTMLAttributes, PointerEvent } from 'react'
import './tilt-card.css'

export interface TiltCardProps extends HTMLAttributes<HTMLDivElement> {
  /** Maximum rotation in degrees, from 0 to 30. */
  maxRotation?: number
  /** Distance to the viewer in pixels. */
  perspective?: number
}

export function TiltCard({
  children,
  className = '',
  maxRotation = 8,
  perspective = 900,
  style,
  onPointerMove,
  onPointerLeave,
  onPointerCancel,
  ...props
}: TiltCardProps) {
  const rotation = Number.isFinite(maxRotation) ? Math.max(0, Math.min(30, maxRotation)) : 8
  const depth = Number.isFinite(perspective) ? Math.max(100, perspective) : 900

  function resetTilt(element: HTMLDivElement) {
    element.style.removeProperty('--ac-tilt-x')
    element.style.removeProperty('--ac-tilt-y')
  }

  function tilt(event: PointerEvent<HTMLDivElement>) {
    onPointerMove?.(event)
    if (
      event.defaultPrevented ||
      event.pointerType !== 'mouse' ||
      window.matchMedia('(prefers-reduced-motion: reduce), (pointer: coarse)').matches
    ) return

    const bounds = event.currentTarget.getBoundingClientRect()
    if (!bounds.width || !bounds.height) return
    const x = Math.max(-1, Math.min(1, ((event.clientX - bounds.left) / bounds.width - 0.5) * 2))
    const y = Math.max(-1, Math.min(1, ((event.clientY - bounds.top) / bounds.height - 0.5) * 2))
    event.currentTarget.style.setProperty('--ac-tilt-x', `${-y * rotation}deg`)
    event.currentTarget.style.setProperty('--ac-tilt-y', `${x * rotation}deg`)
  }

  return (
    <div
      {...props}
      className={`ac-tilt-card ${className}`.trim()}
      style={{ '--ac-tilt-perspective': `${depth}px`, ...style } as CSSProperties}
      onPointerMove={tilt}
      onPointerLeave={(event) => {
        onPointerLeave?.(event)
        resetTilt(event.currentTarget)
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event)
        resetTilt(event.currentTarget)
      }}
    >
      {children}
    </div>
  )
}

.ac-tilt-card {
  position: relative;
  border: 1px solid var(--ac-card-border, rgb(255 255 255 / 12%));
  border-radius: var(--ac-card-radius, 16px);
  background: var(--ac-card-surface, #191b18);
  color: var(--ac-card-color, #e9e9df);
  transform: perspective(var(--ac-tilt-perspective, 900px)) rotateX(var(--ac-tilt-x, 0deg)) rotateY(var(--ac-tilt-y, 0deg));
  transform-style: preserve-3d;
  transition: transform 200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.ac-tilt-card:focus-within {
  outline: 2px solid var(--ac-focus-color, #d7ee9e);
  outline-offset: 5px;
}

@media (prefers-reduced-motion: reduce), (pointer: coarse), (hover: none) {
  .ac-tilt-card {
    transform: none;
    transition: none;
  }
}

import type { CSSProperties, HTMLAttributes } from 'react'
import './border-beam.css'

export interface BorderBeamProps extends HTMLAttributes<HTMLDivElement> {
  /** Seconds for the light to travel once around the edge. */
  duration?: number
  color?: string
  paused?: boolean
}

/** A luminous edge that leaves child content and focus outlines unobstructed. */
export function BorderBeam({
  children,
  className = '',
  duration = 8,
  color = '#f19451',
  paused = false,
  style,
  ...props
}: BorderBeamProps) {
  const seconds = Number.isFinite(duration) ? Math.min(180, Math.max(1, duration)) : 8
  const beamColor = color.trim()
  const safeColor = beamColor && beamColor.length <= 200 && !/[;{}<>]/.test(beamColor)
    ? beamColor
    : '#f19451'

  return (
    <div
      {...props}
      className={`ac-border-beam ${className}`.trim()}
      data-paused={paused || undefined}
      style={{
        '--ac-border-beam-duration': `${seconds}s`,
        '--ac-border-beam-color': safeColor,
        ...style,
      } as CSSProperties}
    >
      {children}
    </div>
  )
}

@property --ac-border-beam-angle {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

.ac-border-beam {
  position: relative;
  isolation: isolate;
  border: 1px solid var(--ac-border-beam-border, rgb(255 255 255 / 13%));
  border-radius: var(--ac-border-beam-radius, 18px);
  background: var(--ac-border-beam-surface, #191817);
  color: var(--ac-border-beam-foreground, #f4efe8);
}

.ac-border-beam::after {
  position: absolute;
  z-index: 1;
  inset: -1px;
  padding: var(--ac-border-beam-width, 1px);
  border-radius: inherit;
  background: conic-gradient(
    from var(--ac-border-beam-angle),
    transparent 0deg 220deg,
    var(--ac-border-beam-color, #f19451) 290deg,
    #fff4e4 315deg,
    transparent 320deg 360deg
  );
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  animation: ac-border-beam-orbit var(--ac-border-beam-duration, 8s) linear infinite;
  pointer-events: none;
  content: '';
}

.ac-border-beam[data-paused]::after {
  animation-play-state: paused;
}

@keyframes ac-border-beam-orbit {
  to { --ac-border-beam-angle: 360deg; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-border-beam::after {
    animation: none;
    --ac-border-beam-angle: 35deg;
  }
}

@media (forced-colors: active) {
  .ac-border-beam {
    border-color: CanvasText;
  }

  .ac-border-beam::after {
    display: none;
  }
}

