  font: inherit;
  font-size: 0.875rem;
  cursor: pointer;
  transform: translateY(-50%);
}

.ac-marquee__toggle:focus-visible {
  outline: 2px solid var(--ac-focus, #6d782e);
  outline-offset: -5px;
}

@keyframes ac-marquee-scroll {
  to { transform: translate3d(-50%, 0, 0); }
}

@media (prefers-reduced-motion: reduce) {
  .ac-marquee {
    overflow-x: auto;
  }

  .ac-marquee__track {
    animation: none;
  }

  .ac-marquee__duplicate,
